import sys,json; sys.path.insert(0,'/tmp/dbtest')
exec(open('/tmp/dbtest/e2e_full.py').read().split("# ---------- seed")[0])
PRJ=q1("select id from public.projects order by created_at limit 1")
CUS=q1(f"select customer_id from public.projects where id='{PRJ}'"); QID=q1(f"select quotation_id from public.projects where id='{PRJ}'"); ORD=q1(f"select order_id from public.projects where id='{PRJ}'")
def ok_(name,sql,sub=OWNER,role='authenticated',expect=True,show=False):
    ok,r=call(role,sql,sub=sub); check(name, ok==expect, r)
    if show: print('   ->',str(r)[:170])
    return r
print('=== R. Site visit'); 
ok_('site visit booked',f"select public.create_site_visit('{QID}','{CUS}',current_date+2,'10:00','site_survey','{DRIVER}','Bring moisture meter')",show=True)
SV=q1("select id from public.site_visits order by created_at desc limit 1")
ok_('site visit completed',f"select public.update_site_visit_status('{SV}','completed','Measured 500 sqm')")
ok_('completed visit cannot be rescheduled',f"select public.update_site_visit_status('{SV}','scheduled',NULL)",expect=False,show=True)
print('=== S. Service case (warranty)')
ok_('service case opened',f"select public.create_service_case('{CUS}','Coating peeling at joint','Edge lifting after 2 weeks','warranty','high','{PRJ}','{ORD}')",show=True)
CASE=q1("select id from public.service_cases order by created_at desc limit 1")
ok_('case cannot jump open -> closed',f"select public.transition_service_case_360('{CASE}','closed',NULL,NULL,NULL,NULL,NULL)",expect=False,show=True)
ok_('case in review',f"select public.transition_service_case_360('{CASE}','in_review',NULL,NULL,NULL,NULL,'Reviewing photos')")
ok_('scheduled needs a date',f"select public.transition_service_case_360('{CASE}','scheduled',NULL,NULL,NULL,NULL,NULL)",expect=False,show=True)
ok_('case scheduled with a date',f"select public.transition_service_case_360('{CASE}','scheduled',NULL,'{DRIVER}',current_date+1,NULL,NULL)")
ok_('case in progress',f"select public.transition_service_case_360('{CASE}','in_progress',NULL,NULL,NULL,NULL,NULL)")
ok_('resolving needs a resolution',f"select public.transition_service_case_360('{CASE}','resolved',NULL,NULL,NULL,NULL,NULL)",expect=False,show=True)
ok_('case resolved with resolution',f"select public.transition_service_case_360('{CASE}','resolved',NULL,NULL,NULL,'Re-coated joint',NULL)")
print('  service-case notifications:',q1("select count(*) from public.communication_outbox where subject ilike '%service%' or message ilike '%service%'"))
print('=== T. Maintenance plan')
PLAN=q1("select id from public.maintenance_plans order by created_at desc limit 1")
print('  visits table rows:',q1("select count(*) from public.maintenance_visits"),'| tables:',q1("select string_agg(table_name,',') from information_schema.tables where table_schema='public' and table_name ilike 'maintenance%'"))
VIS=q1(f"select id from public.maintenance_visits where plan_id='{PLAN}' order by created_at desc limit 1")
ok_('visit completed',f"select public.complete_maintenance_visit_360('{VIS}',current_date,'All good')",show=True)
ok_('plan resumed/active',f"select public.transition_maintenance_plan_360('{PLAN}','active',NULL)")
print(f"\n{sum(1 for _,c in results if c)}/{len(results)} checks passed")
